<?php
declare(strict_types=1);
function read_api(PDO $db,array $auth,string $path,string $method): bool {
    if($method!=='GET'||!in_array($path,['/api/search','/api/tracks','/api/albums'],true)&&!preg_match('~^/api/albums/[0-9A-HJKMNP-TV-Z]{26}$~',$path))return false;$limit=$_GET['limit']??'100';if(!preg_match('/^[1-9]\d*$/D',$limit)||(int)$limit>500)fail('validation','Use a valid result limit.');$limit=(int)$limit;$uid=$auth['user']['id'];$columns=implode(',',array_map(fn($column)=>'t.'.$column,['id','owner_id','album_id','artist_id','title','artist_name','album_artist','album_title','track_no','disc_no','year','genre','duration_ms','codec','container','mime','original_name','original_path','visibility','rev','added_at','updated_at','size_bytes']));
    $words=function(string $value):array{if(mb_strlen($value)>200)fail('validation','Use a search of up to 200 characters.');return array_slice(preg_split('/\s+/u',mb_strtolower(trim($value)),-1,PREG_SPLIT_NO_EMPTY),0,12);};$like=fn($value)=>'%'.addcslashes($value,'\\%_').'%';
    if($path==='/api/search'||$path==='/api/tracks'){$terms=$words($_GET['q']??'');$where=array_fill(0,count($terms),"(lower(t.title||' '||t.artist_name||' '||COALESCE(t.album_title,'')||' '||COALESCE(t.original_path,'')||' '||COALESCE(t.genre,'')) LIKE ? ESCAPE '\\')");$params=[$uid,...array_map($like,$terms)];if(isset($_GET['ids'])){$ids=journal_ids(explode(',',$_GET['ids']),'Track IDs');if(count($ids)>500)fail('validation','Read up to 500 tracks at once.');$where[]='t.id IN('.implode(',',array_fill(0,count($ids),'?')).')';$params=[...$params,...$ids];}$sql='SELECT '.$columns." FROM tracks t WHERE t.deleted=0 AND(t.owner_id=? OR t.visibility='public')".($where?' AND '.implode(' AND ',$where):'').' ORDER BY t.title,t.id LIMIT '.$limit;reply(['items'=>query_all($db,$sql,$params),'nextCursor'=>null]);}
    if($path==='/api/albums'){$terms=$words($_GET['filter']??'');$cursor=$_GET['cursor']??null;if($cursor)journal_ids([$cursor]);$sql="SELECT a.*,COALESCE(a.artist_name,ar.name) AS artist_name FROM albums a LEFT JOIN artists ar ON ar.id=a.artist_id WHERE a.deleted=0 AND(a.owner_id=? OR a.visibility='public')".str_repeat(" AND lower(a.title||' '||COALESCE(a.artist_name,ar.name,'')) LIKE ? ESCAPE '\\'",count($terms)).($cursor?' AND a.id>?':'').' ORDER BY a.id LIMIT '.($limit+1);$rows=query_all($db,$sql,[$uid,...array_map($like,$terms),...($cursor?[$cursor]:[])]);reply(['items'=>array_slice($rows,0,$limit),'nextCursor'=>count($rows)>$limit?$rows[$limit-1]['id']:null]);}
    if(preg_match('~^/api/albums/([0-9A-HJKMNP-TV-Z]{26})$~',$path,$match)){$album=album_row($db,$match[1]);if(!$album||$album['deleted'])fail('not_found','Album not found.',404);if($album['owner_id']!==$uid&&$album['visibility']!=='public')fail('forbidden','This album is private.',403);$tracks=query_all($db,'SELECT '.$columns." FROM tracks t WHERE t.album_id=? AND t.deleted=0 AND(t.owner_id=? OR t.visibility='public') ORDER BY t.disc_no,t.track_no,t.title LIMIT 2000",[$album['id'],$uid]);reply(['album'=>$album,'tracks'=>$tracks]);}return false;
}
